mapper.select:
SELECT H.GA_NO AS GP_NO, H.CITY_CODE || ' ' || NVL(H.PLATE_CODE, '') || ' ' || H.VEH_NO AS VEHICLE, TO_CHAR(H.CREATED_ON, 'dd-mm-yyyy hh24:mi') AS GP_DATE, NULL AS GP_TYPE, NULL AS GP_REF_NO, NULL AS CONTR_NO, NULL AS SEAL_NO, (SELECT B.MARKS_NO FROM BOL B WHERE B.ROTN = D.ROTATION_NO AND B.BOL_NO = D.BOL_NO AND D.BOL_UNIQ_ID = B.BOL_UNIQUE_IND AND D.BOL_SPLIT_ID = B.BOL_SPLIT) AS MARKS_NOS, (SELECT V.PARTY_NAME FROM GATE_ADVICE_REQUEST GA, V_PARTY_FULL V WHERE GA.GA_REQ_ID = H.GA_REQ_ID AND GA.CONSIGNEE_CODE = V.PARTY_CODE AND V.CUSTOMER_TYPE = GA.CONSIGNEE_TYPE AND V.IS_PARTY_VALID = 1 AND V.IS_ROLE_VALID = 1) AS CUST_NAME, NULL AS CONTR_SIZE, NULL AS CHASIS_UNIT, NULL AS CHASISNO, NULL AS INSPN_AUTH, NULL AS ACTION_DESC, NULL AS INSP_REMARKS, NULL AS REMARKS, NULL AS SOUTH_JAFZA, NULL AS CUST_HOLD, NULL AS CUST_REMARKS, NULL AS GP_STATUS, TO_CHAR(H.GA_EXPIRY_DATE, 'dd-mm-yyyy hh24:mi') AS GP_EXPDATE, DECODE(H.CARGO_TYPE, 'VC', 'VEHICLE CARGO', 'BC', 'BULK', 'GC') AS CARGO_TYPE, D.ROTATION_NO, D.BOL_NO, D.BOL_UNIQ_ID, D.BOL_SPLIT_ID, D.CON_SR_NO, D.Doc_No AS BOENO, (SELECT GC.CARGO_CATEGORY_DESC FROM GCB_CARGO_CAT_MAPPING_DTLS GD, GCB_CARGO_CATEGORY GC WHERE GC.CARGO_CATEGORY_ID = GD.CARGO_CATEGORY_ID AND GD.DETAIL_ID = D.DETAIL_ID) AS GOOD_DESCRIPTION, (SELECT CD.CODE_DESC1 FROM GCB_CARGO_CAT_MAPPING_DTLS GD,CODES CD WHERE GD.DETAIL_ID = D.DETAIL_ID AND CD.CODE_CODE=GD.PKG_TYPE AND CD.code_type = 'PACKAGE' ) AS PKG_TYP, NVL(D.QTY, D.WEIGHT) AS GP_ITEM_QTY, D.WEIGHT AS GP_ITEM_WT, NULL AS GATE_NO FROM GATE_ADVICE_HDR H, GATE_ADVICE_DTLS D WHERE H.GA_ID = D.GA_ID AND H.CITY_CODE = #{CITY_CODE} AND H.VEH_NO = #{VEH_NO}
AND H.PLATE_CODE = #{PLT_CODE}
AND (H.IS_SELF_DRIVEN IS NULL OR H.IS_SELF_DRIVEN != 1) AND H.GA_EXPIRY_DATE > SYSDATE AND H.IS_VALID=1 AND H.GA_STATUS='A' AND D.DOC_TYPE = 'BOL'
union
SELECT H.GA_NO AS GP_NO, H.CITY_CODE || ' ' || NVL(H.PLATE_CODE, '') || ' ' || H.VEH_NO AS VEHICLE, TO_CHAR(H.CREATED_ON, 'dd-mm-yyyy hh24:mi') AS GP_DATE, NULL AS GP_TYPE, NULL AS GP_REF_NO, NULL AS CONTR_NO, NULL AS SEAL_NO, (select ci.MARKS_NOS from cargo_Item ci, export_booking exb where exb.rotation_no = D.rotation_no AND exb.agent_brn = D.bol_no AND exb.export_booking_id = ci.export_booking_id and CI.CARGO_CATEGORY_ID = D.DETAIL_ID ) AS MARKS_NOS, (SELECT V.PARTY_NAME FROM GATE_ADVICE_REQUEST GA, V_PARTY_FULL V WHERE GA.GA_REQ_ID = H.GA_REQ_ID AND GA.CONSIGNEE_CODE = V.PARTY_CODE AND V.CUSTOMER_TYPE = GA.CONSIGNEE_TYPE AND V.IS_PARTY_VALID = 1 AND V.IS_ROLE_VALID = 1) AS CUST_NAME, NULL AS CONTR_SIZE, NULL AS CHASIS_UNIT, NULL AS CHASISNO, NULL AS INSPN_AUTH, NULL AS ACTION_DESC, NULL AS INSP_REMARKS, NULL AS REMARKS, NULL AS SOUTH_JAFZA, NULL AS CUST_HOLD, NULL AS CUST_REMARKS, NULL AS GP_STATUS, TO_CHAR(H.GA_EXPIRY_DATE, 'dd-mm-yyyy hh24:mi') AS GP_EXPDATE, DECODE(H.CARGO_TYPE, 'VC', 'VEHICLE CARGO', 'BC', 'BULK', 'GC') AS CARGO_TYPE, D.ROTATION_NO, D.BOL_NO, NULL, NULL, D.CON_SR_NO, D.BOL_NO AS BOENO, (SELECT GC.CARGO_CATEGORY_DESC FROM GCB_CARGO_CAT_MAPPING_DTLS GD, GCB_CARGO_CATEGORY GC WHERE GC.CARGO_CATEGORY_ID = GD.CARGO_CATEGORY_ID AND GD.DETAIL_ID = D.DETAIL_ID) AS GOOD_DESCRIPTION, (SELECT CD.CODE_DESC1 FROM GCB_CARGO_CAT_MAPPING_DTLS GD,CODES CD WHERE GD.DETAIL_ID = D.DETAIL_ID AND CD.CODE_CODE=GD.PKG_TYPE AND CD.code_type = 'PACKAGE' ) AS PKG_TYP, NVL(D.QTY, D.WEIGHT) AS GP_ITEM_QTY, D.WEIGHT AS GP_ITEM_WT, NULL AS GATE_NO FROM GATE_ADVICE_HDR H, GATE_ADVICE_DTLS D WHERE H.GA_ID = D.GA_ID AND H.CITY_CODE = #{CITY_CODE} AND H.VEH_NO = #{VEH_NO}
AND H.PLATE_CODE = #{PLT_CODE}
AND (H.IS_SELF_DRIVEN IS NULL OR H.IS_SELF_DRIVEN != 1) AND H.GA_EXPIRY_DATE > SYSDATE AND H.IS_VALID=1 AND H.GA_STATUS='A' AND D.DOC_TYPE = 'BRN'
